def replace_locale_value(path: Path, key: str, next_key: str, value: str):
    text = path.read_text()
    start_marker = f'      {key}:'
    end_marker = f'      {next_key}:'
    start = text.index(start_marker)
    end = text.index(end_marker, start)
    replacement = f'      {key}: {value!r},\n'
    path.write_text(text[:start] + replacement + text[end:])

